 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append((color, cells))
    # The repeated object is the largest connected non-background component;
    # singleton components of another color are placement markers.
    color, cells = max(comps, key=lambda item: len(item[1]))
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    template = {(r-r0, c-c0): grid[r][c] for r, c in cells}
    ar, ac = (r1-r0)//2, (c1-c0)//2
    out = [row[:] for row in grid]
    for marker_color, marker_cells in comps:
        if marker_color == color or len(marker_cells) != 1:
            continue
        mr, mc = marker_cells[0]
        out[mr][mc] = bg
        for (dr, dc), value in template.items():
            rr, cc = mr + dr - ar, mc + dc - ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
